const input = $input.first().json;
const body = input.body ?? {};
const runId = Number(body.run_id);
const months = Number(body.months ?? 12);

if (!Number.isSafeInteger(runId) || runId < 1) {
  throw new Error('Invalid run_id');
}

if (!Number.isSafeInteger(months) || months < 1 || months > 36) {
  throw new Error('Invalid months');
}

const requestedAt = body.requested_at ? new Date(body.requested_at) : new Date();
if (Number.isNaN(requestedAt.getTime())) {
  throw new Error('Invalid requested_at');
}

const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Bangkok',
    year: 'numeric',
    month: 'numeric',
  })
    .formatToParts(requestedAt)
    .filter((part) => ['year', 'month'].includes(part.type))
    .map((part) => [part.type, part.value]),
);

const year = Number(parts.year);
const month = Number(parts.month);
const nextYear = month === 12 ? year + 1 : year;
const nextMonth = month === 12 ? 1 : month + 1;
const expectedMonth = `${nextYear}-${String(nextMonth).padStart(2, '0')}-01`;

return [{
  json: {
    run_id: runId,
    months,
    requested_by: body.requested_by ?? null,
    requested_at: requestedAt.toISOString(),
    expected_month: expectedMonth,
    execution_id: String($execution.id),
  },
}];

const context = $('Run context').first().json;
const rows = $input.all().flatMap((item) =>
  Array.isArray(item.json) ? item.json : [item.json]
);
const claimed = rows.find((row) => Number(row.run_id) === context.run_id);

if (!claimed) {
  throw new Error('Run was not claimed; another n8n execution may own it');
}

return [{ json: { ...context, run: claimed } }];

const aiResult = $input.first().json;

const output =
  aiResult.output ??
  aiResult.text ??
  aiResult.response ??
  aiResult;

let parsed;

if (typeof output === 'string') {
  const cleaned = output
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');

  parsed = JSON.parse(cleaned);
} else {
  parsed = output;
}

if (
  !Array.isArray(parsed.predictions) ||
  parsed.predictions.length === 0
) {
  throw new Error('AI did not return predictions');
}

// ต้องตรงกับชื่อ HTTP Request Node บน Canvas
let source = $('Get analysis data').first().json;

if (typeof source === 'string') {
  source = JSON.parse(source);
}

if (!Array.isArray(source.products) || source.products.length === 0) {
  throw new Error('No products found in analysis data');
}

const allowedProductIds = new Set(
  source.products.map((product) => Number(product.product_id)),
);

// คำนวณเดือนถัดไปตามเวลาไทย
const context = $('Run context').first().json;
const expectedMonth = context.expected_month;

const seenProductIds = new Set();

const predictions = parsed.predictions.map((item) => {
  const productId = Number(item.product_id);
  const quantity = Number(item.predicted_quantity);
  const predictedMonth =
    String(item.predicted_month ?? '').slice(0, 10);

  if (!Number.isInteger(productId) || !allowedProductIds.has(productId)) {
    throw new Error(`Unknown product_id: ${item.product_id}`);
  }

  if (seenProductIds.has(productId)) {
    throw new Error(`Duplicate product_id: ${productId}`);
  }

  if (!Number.isFinite(quantity)) {
    throw new Error(`Invalid quantity for product_id: ${productId}`);
  }

  if (predictedMonth !== expectedMonth) {
    throw new Error(
      `Invalid month for product_id ${productId}. Expected ${expectedMonth}`,
    );
  }

  seenProductIds.add(productId);

  return {
    product_id: productId,
    predicted_quantity: Math.max(0, Math.round(quantity)),
    predicted_month: predictedMonth,
  };
});

const missingProductIds = [...allowedProductIds].filter(
  (productId) => !seenProductIds.has(productId),
);

if (missingProductIds.length > 0) {
  throw new Error(
    `AI omitted product IDs: ${missingProductIds.join(', ')}`,
  );
}

return [{
  json: {
    run_id: context.run_id,
    execution_id: context.execution_id,
    predictions,
    predicted_month: expectedMonth,
    prediction_count: predictions.length,
  },
}];

const normalized = $('Normalize predictions').first().json.predictions;
const expectedIds = new Set(normalized.map((item) => Number(item.product_id)));
const rows = $input.all()
  .flatMap((item) => Array.isArray(item.json) ? item.json : [item.json])
  .filter((row) => row && row.prediction_id != null && Number.isSafeInteger(Number(row.product_id)));
const savedIds = new Set(rows.map((row) => Number(row.product_id)));

if (
  rows.length !== normalized.length ||
  savedIds.size !== expectedIds.size ||
  [...expectedIds].some((productId) => !savedIds.has(productId))
) {
  throw new Error(`Saved ${rows.length} of ${normalized.length} predictions`);
}

return [{ json: { saved_count: rows.length } }];

const runId = $('Run context').first().json.run_id;
const rows = $input.all().flatMap((item) =>
  Array.isArray(item.json) ? item.json : [item.json]
);
const completed = rows.find((row) =>
  Number(row.run_id) === runId && row.status === 'completed'
);

if (!completed) {
  throw new Error('Run was not completed; it may have expired or lost ownership');
}

return [{ json: completed }];
